const coreVisualPages=new Set(['links.html','index.html','products.html','brand.html']);
(async()=>{const out='diagnostics/brand-20261003';fs.mkdirSync(out,{recursive:true});let failures=[];let checks=[];
for(const [engine,type] of Object.entries({chromium,webkit})){const browser=await type.launch();for(const [device,viewport] of Object.entries({desktop:{width:1440,height:1000},tablet:{width:768,height:1024},mobile:{width:390,height:844},android:{width:412,height:915},small:{width:320,height:740}})){const context=await browser.newContext({viewport,deviceScaleFactor:1});for(const file of pages){const p=await context.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));await p.goto(base+file,{waitUntil:'networkidle'});await p.evaluate(()=>window.scrollTo(0,document.body.scrollHeight));await p.waitForTimeout(300);await p.evaluate(()=>window.scrollTo(0,0));const r=await p.evaluate(()=>({paper:getComputedStyle(document.body).backgroundColor,overflow:document.documentElement.scrollWidth>innerWidth+1,broken:[...document.images].filter(i=>i.offsetWidth>0&&i.complete&&!i.naturalWidth).map(i=>i.src),manifest:document.querySelector('link[rel="manifest"]')?.getAttribute('href'),cta:[...document.querySelectorAll('.btn-primary,.btn-line,.header-line-cta')].filter(x=>x.offsetWidth>0).map(x=>{const s=getComputedStyle(x);return{text:x.textContent.trim(),bg:s.backgroundColor,bgImage:s.backgroundImage,border:s.borderTopColor,color:s.color}}),name:document.querySelector('meta[name="apple-mobile-web-app-title"]')?.content,links:[...document.querySelectorAll('a[href]')].map(a=>a.getAttribute('href'))}));if(r.overflow||r.broken.length||errs.length||r.name!=='仙加味'||!r.manifest)failures.push({engine,device,file,...r,errs});if(r.paper!=='rgb(247, 244, 237)')failures.push({engine,device,file,error:'brand paper',paper:r.paper});const badCta=r.cta.filter(x=>{const paint=`${x.bg} ${x.bgImage}`;const red=paint.includes('rgb(104, 32, 35)')||paint.includes('rgb(147, 45, 49)')||paint.includes('rgb(79, 23, 25)');const gold=['rgb(176, 138, 71)','rgb(198, 157, 80)'].includes(x.border);return !red||!gold;});if(badCta.length)failures.push({engine,device,file,error:'CTA brand red/gold',cta:badCta});if(file==='links.html'&&!r.links.includes('https://lin.ee/sHZW7NkR'))failures.push({engine,device,file,error:'LINE missing'});const manifestPath=(r.manifest||'').split('?')[0];if(file==='links.html'&&manifestPath!=='links.webmanifest')failures.push({engine,device,file,error:'links manifest mismatch',manifest:r.manifest});if(file!=='links.html'&&manifestPath!=='site.webmanifest')failures.push({engine,device,file,error:'site manifest mismatch',manifest:r.manifest});
if(file==='faq.html'){const detail=p.locator('details').first();if(await detail.count()){if(await detail.getAttribute('open')!==null)await detail.locator('summary').click();await detail.locator('summary').click();if(await detail.getAttribute('open')===null)failures.push({engine,device,file,error:'FAQ failed'});}}
if((device==='mobile'&&visualPages.has(file))||(device==='desktop'&&coreVisualPages.has(file)))await p.screenshot({path:`${out}/${engine}-${device}-${file}.png`,fullPage:true});checks.push({engine,device,file,pass:!r.overflow&&!r.broken.length&&!errs.length});await p.close();}await context.close();}await browser.close();}
for(const file of pages){const raw=fs.readFileSync(file,'utf8');if(raw.includes('\\n'))failures.push({file,error:'public html contains literal backslash-n'});}
for(const file of pages){if(file==='links.html')continue;const html=fs.readFileSync(file,'utf8');if(!html.includes('site-brand-v20261003.css?v=20261003-performance-v19'))failures.push({file,error:'brand css cache version not v19'});if(!html.includes('site.js?v=20261003-performance-v19'))failures.push({file,error:'site js cache version not v19'});}
const sitemapRaw=fs.readFileSync('sitemap.xml','utf8');if(sitemapRaw.includes('\\n'))failures.push({error:'sitemap contains literal \\n'});
for(const file of ['links.html','index.html']){const html=fs.readFileSync(file,'utf8');if(!html.includes('name="color-scheme" content="light"'))failures.push({file,error:'light color scheme metadata missing'});if(!html.includes('name="apple-mobile-web-app-capable" content="yes"'))failures.push({file,error:'apple standalone metadata missing'});if(!html.includes('name="apple-mobile-web-app-status-bar-style" content="default"'))failures.push({file,error:'apple status bar metadata missing'});}
const homeRaw=fs.readFileSync('index.html','utf8');
if(/rel="preload"[^>]+brand-story\.png/.test(homeRaw))failures.push({file:'index.html',error:'unused homepage brand-story preload'});
if(/images\/product-main\/[^"]+"[^>]+loading="eager"/.test(homeRaw))failures.push({file:'index.html',error:'homepage product showcase must lazy-load'});
if((homeRaw.match(/width="362" height="700"/g)||[]).length<2)failures.push({file:'index.html',error:'official logo intrinsic ratio missing'});
if(!homeRaw.includes('"https://www.facebook.com/TAISHING15825868/"'))failures.push({file:'index.html',error:'organization Facebook sameAs missing'});
const coreRaw=fs.readFileSync('site-core-v410.js','utf8');
if(!coreRaw.includes('querySelectorAll("[data-line-message]")'))failures.push({file:'site-core-v410.js',error:'LINE prefill hydration missing'});
if(/line-qr-official\.png[^>]+loading="eager"/.test(coreRaw))failures.push({file:'site-core-v410.js',error:'footer LINE QR must lazy-load'});
for(const file of ['product-guilu-gao.html','product-guilu-drink-30cc.html','product-guilu-drink-180cc.html','product-guilu-tangkuai.html','product-guilu-jiao.html','product-luerong-fen.html']){const html=fs.readFileSync(file,'utf8');if(!html.includes('"@type":"BreadcrumbList"'))failures.push({file,error:'BreadcrumbList missing'});}
const trialLine=fs.readFileSync('trial-line.html','utf8');if(!trialLine.includes('site-brand-v20261003.css?v=20261003-performance-v19')||!trialLine.includes('data-page="trial-line"')||!trialLine.includes('site.webmanifest?v=20261003')||!trialLine.includes('apple-mobile-web-app-title" content="仙加味"')||!trialLine.includes('images/trial/trial-poster-small-boss-official-v20260814.jpg')||!trialLine.includes('https://line.me/R/oaMessage/%40762jybnm/'))failures.push({error:'trial-line redirect bridge invalid'});
const m=JSON.parse(fs.readFileSync('site.webmanifest'));const lm=JSON.parse(fs.readFileSync('links.webmanifest'));if(m.name!=='仙加味'||m.short_name!=='仙加味'||m.id!=='./'||m.start_url!=='./index.html'||!m.icons.some(x=>x.purpose==='maskable'))failures.push({error:'site manifest invalid',manifest:m});if(lm.name!=='仙加味'||lm.short_name!=='仙加味'||lm.id!=='./links.html'||lm.start_url!=='./links.html'||!lm.icons.some(x=>x.purpose==='maskable'))failures.push({error:'links manifest invalid',manifest:lm});fs.writeFileSync(out+'/report.json',JSON.stringify({base,pages,checks,manifests:{site:m,links:lm},failures},null,2));console.log(JSON.stringify({checks:checks.length,failures},null,2));if(failures.length)process.exit(1);})().catch(e=>{console.error(e);process.exit(1)});
